def normalizar_cep(cep):
    """Remove pontos e traço do CEP e devolve só os 8 dígitos."""
    return re.sub(r"\D", "", cep)

def validar_cep(cep):
    """Diz se o CEP tem exatamente 8 dígitos depois de normalizado."""
    return len(normalizar_cep(cep)) == 8

def regiao_do_cep(cep):
    """Descobre a região do país pelo primeiro dígito do CEP. Levanta ValueError se o CEP for inválido."""
    if not validar_cep(cep):
        raise ValueError(f"CEP inválido: {cep!r}")
    return REGIOES[normalizar_cep(cep)[0]]

@dataclass
class Pedido:
    """Pedido de um cliente, com CEP de destino e lista de itens."""
    cep_destino: str
    itens: list = field(default_factory=list)
    fechado: bool = False

def adicionar_item(self, item):
    """Adiciona um item ao pedido. Pedido já fechado não aceita itens novos."""
    if self.fechado:
        raise RuntimeError("pedido fechado não aceita itens")
    self.itens.append(item)

def peso_total(self):
    """Soma o peso de todos os itens, considerando a quantidade de cada um."""
    return sum(i.peso_kg * i.quantidade for i in self.itens)

def volume_total(self):
    """Soma o volume de todos os itens, considerando a quantidade de cada um."""
    return sum(i.volume_cm3 * i.quantidade for i in self.itens)

def valor_frete(self, urgente=False):
    """Calcula o frete do pedido inteiro usando a região do CEP de destino."""
    return calcular_frete(self.peso_total(), self.volume_total(), regiao_do_cep(self.cep_destino), urgente)

def fechar(self):
    """Fecha o pedido para novas alterações. Pedido sem itens não pode ser fechado."""
    if not self.itens:
        raise ValueError("pedido vazio")
    self.fechado = True

def proximo_dia_util(data):
    """Se a data cair no sábado ou domingo, avança para a segunda-feira."""
    while data.weekday() >= 5:
        data += timedelta(days=1)
    return data

def gerar_codigo_rastreio(pedido_id):
    """Gera o código de rastreio no formato FR + 8 dígitos + BR a partir do número do pedido."""
    return f"FR{pedido_id:08d}BR"

def validar_codigo_rastreio(codigo):
    """Confere se o código de rastreio segue o formato FR + 8 dígitos + BR."""
    return bool(PADRAO_CODIGO.match(codigo))

@dataclass
class EventoRastreio:
    """Um evento do rastreio: status, local e data."""
    status: str
    local: str
    data: str

def classificar_pacote(peso_kg, volume_cm3):
    """Define o porte do pacote (P, M ou G) pelo peso e pelo volume."""
    if peso_kg <= 1 and volume_cm3 <= 4000:
        return "P"
    if peso_kg <= 5 and volume_cm3 <= 20000:
        return "M"
    return "G"

def calcular_frete(peso_kg, volume_cm3, regiao, urgente=False):
    """Calcula o valor do frete em reais pelo porte e pela região. Entrega urgente soma 40%."""
    if regiao not in FATOR_REGIAO:
        raise ValueError(f"região desconhecida: {regiao}")
    valor = TARIFA_BASE[classificar_pacote(peso_kg, volume_cm3)] * FATOR_REGIAO[regiao]
    if urgente:
        valor *= 1 + ADICIONAL_URGENTE
    return arredondar_moeda(valor)

def aplicar_cupom(valor, cupom):
    """Aplica um cupom de desconto ao frete. Cupom que não existe não altera o valor."""
    desconto = CUPONS.get(cupom.upper(), 0.0)
    return arredondar_moeda(valor * (1 - desconto))

def arredondar_moeda(valor):
    """Arredonda um valor para 2 casas decimais, metade para cima."""
    return float(Decimal(str(valor)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

def formatar_real(valor):
    """Formata um número como moeda brasileira, por exemplo R$ 1.234,50."""
    texto = f"{arredondar_moeda(valor):,.2f}"
    return "R$ " + texto.replace(",", "X").replace(".", ",").replace("X", ".")
